/**
 * Cart Controller
 * Generated by BackendForge
 */
const { Cart, Product } = require('../models');

const cartController = {
  async getCart(req, res, next) {
    try {
      let cart = await Cart.findOne({ where: { userId: req.userId } });
      if (!cart) {
        cart = await Cart.create({ userId: req.userId, items: [], totalAmount: 0 });
      }
      res.json({ success: true, data: { cart } });
    } catch (error) { next(error); }
  },

  async addToCart(req, res, next) {
    try {
      const { productId, quantity, variant } = req.body;
      const product = await Product.findByPk(productId);
      if (!product || !product.isActive) {
        return res.status(404).json({ success: false, message: 'Product not found or unavailable' });
      }
      if (product.stock < quantity) {
        return res.status(400).json({ success: false, message: `Only ${product.stock} items in stock` });
      }

      let cart = await Cart.findOne({ where: { userId: req.userId } });
      if (!cart) cart = await Cart.create({ userId: req.userId, items: [], totalAmount: 0 });

      const items = [...(cart.items || [])];
      const existingIdx = items.findIndex(i => i.productId === productId);
      if (existingIdx >= 0) {
        items[existingIdx].quantity += quantity;
      } else {
        items.push({
          productId, name: product.name, price: parseFloat(product.price),
          quantity, image: product.images?.[0]?.url, variant,
        });
      }
      const totalAmount = items.reduce((sum, i) => sum + (i.price * i.quantity), 0);
      await cart.update({ items, totalAmount });

      res.json({ success: true, message: 'Item added to cart', data: { cart } });
    } catch (error) { next(error); }
  },

  async updateCartItem(req, res, next) {
    try {
      const { quantity } = req.body;
      const cart = await Cart.findOne({ where: { userId: req.userId } });
      if (!cart) return res.status(404).json({ success: false, message: 'Cart not found' });
      const items = [...(cart.items || [])];
      const idx = items.findIndex(i => i.productId === req.params.itemId);
      if (idx < 0) return res.status(404).json({ success: false, message: 'Item not found' });
      items[idx].quantity = quantity;
      const totalAmount = items.reduce((sum, i) => sum + (i.price * i.quantity), 0);
      await cart.update({ items, totalAmount });
      res.json({ success: true, message: 'Cart updated', data: { cart } });
    } catch (error) { next(error); }
  },

  async removeCartItem(req, res, next) {
    try {
      const cart = await Cart.findOne({ where: { userId: req.userId } });
      if (!cart) return res.status(404).json({ success: false, message: 'Cart not found' });
      const items = (cart.items || []).filter(i => i.productId !== req.params.itemId);
      const totalAmount = items.reduce((sum, i) => sum + (i.price * i.quantity), 0);
      await cart.update({ items, totalAmount });
      res.json({ success: true, message: 'Item removed', data: { cart } });
    } catch (error) { next(error); }
  },

  async clearCart(req, res, next) {
    try {
      await Cart.update({ items: [], totalAmount: 0 }, { where: { userId: req.userId } });
      res.json({ success: true, message: 'Cart cleared' });
    } catch (error) { next(error); }
  },
};

module.exports = cartController;
